#!/bin/sh
scan_environment() { ENV_KIND=unknown; ENV_RUNTIME=unknown; ENV_ORCHESTRATOR=unknown; _c=$(read_one /proc/1/cgroup); [ -e "$(path /.dockerenv)" ] && { ENV_KIND=container; ENV_RUNTIME=docker; }; [ -e "$(path /run/.containerenv)" ] && { ENV_KIND=container; ENV_RUNTIME=podman; }; case $_c in *kubepods*) ENV_KIND=container; ENV_ORCHESTRATOR=kubernetes;; *docker*) ENV_KIND=container; [ "$ENV_RUNTIME" = unknown ] && ENV_RUNTIME=docker;; *libpod*) ENV_KIND=container; ENV_RUNTIME=podman;; *lxc*) ENV_KIND=container; ENV_RUNTIME=lxc;; *machine.slice*) ENV_KIND=container; ENV_RUNTIME=systemd_nspawn;; esac; _virt=$(read_one /sys/class/dmi/id/sys_vendor); case $_virt in *QEMU*|*KVM*|*VMware*|*VirtualBox*|*Microsoft*) [ "$ENV_KIND" = container ] || { ENV_KIND=virtual_machine; ENV_RUNTIME=$(printf '%s' "$_virt" | tr ' ' '_'); };; esac; }
environment_json() { printf '{"kind":'; json_quote "$ENV_KIND"; printf ',"runtime":'; json_quote "$ENV_RUNTIME"; printf ',"orchestrator":'; json_quote "$ENV_ORCHESTRATOR"; printf ',"evidence":"cgroup, marker files, DMI"}'; }
